
/* ===== Original script block 1 ===== */
(function () {
  var root = document.documentElement;
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var fine = window.matchMedia && window.matchMedia('(hover: hover) and (pointer: fine)').matches;

  /* copy buttons */
  function flash(btn) {
    var old = btn.getAttribute('data-label') || btn.textContent;
    btn.setAttribute('data-label', old);
    btn.textContent = 'Copied';
    setTimeout(function () { btn.textContent = old; }, 1400);
  }
  function fallback(text, btn) {
    var t = document.createElement('textarea');
    t.value = text; t.setAttribute('readonly', '');
    t.style.position = 'fixed'; t.style.opacity = '0';
    document.body.appendChild(t); t.select();
    try { document.execCommand('copy'); flash(btn); } catch (e) {}
    document.body.removeChild(t);
  }
  document.querySelectorAll('[data-copy]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var text = btn.getAttribute('data-copy');
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () { flash(btn); }, function () { fallback(text, btn); });
      } else { fallback(text, btn); }
    });
  });

  /* theme toggle */
  var tgl = document.getElementById('theme');
  function current() {
    var t = root.getAttribute('data-theme');
    if (t) return t;
    return window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
  }
  function label() { tgl.textContent = current() === 'dark' ? 'Light mode' : 'Dark mode'; }
  tgl.addEventListener('click', function () {
    root.setAttribute('data-theme', current() === 'dark' ? 'light' : 'dark');
    label();
  });
  label();

  /* typewriter role */
  var el = document.getElementById('type');
  if (el && !reduce) {
    var words = ['Aspiring Software Developer', 'Java and Python Programming', 'Test Automation with Playwright and Pytest'];
    var wi = 0, ci = words[0].length, erasing = true;
    function tick() {
      var w = words[wi], delay;
      if (erasing) {
        ci--; delay = 45;
        if (ci <= 0) { erasing = false; wi = (wi + 1) % words.length; w = words[wi]; delay = 350; }
      } else {
        ci++; delay = 80;
        if (ci >= w.length) { erasing = true; delay = 2000; }
      }
      el.textContent = words[wi].slice(0, Math.max(ci, 0));
      if (ci <= 0) el.textContent = ' ';
      setTimeout(tick, delay);
    }
    setTimeout(tick, 2200);
  }

  /* cursor spotlight and card tilt, only for mouse users */
  if (fine && !reduce) {
    window.addEventListener('pointermove', function (e) {
      root.style.setProperty('--mx', e.clientX + 'px');
      root.style.setProperty('--my', e.clientY + 'px');
    }, { passive: true });
    document.querySelectorAll('.tilt').forEach(function (c) {
      c.addEventListener('pointermove', function (e) {
        var r = c.getBoundingClientRect();
        var x = (e.clientX - r.left) / r.width - 0.5;
        var y = (e.clientY - r.top) / r.height - 0.5;
        c.style.transform = 'perspective(900px) rotateX(' + (-y * 6).toFixed(2) + 'deg) rotateY(' + (x * 8).toFixed(2) + 'deg) translateY(-4px)';
      });
      c.addEventListener('pointerleave', function () { c.style.transform = ''; });
    });
  }

  /* project slider arrows, shown only when the cards overflow */
  var track = document.getElementById('track');
  var ctrl = document.getElementById('ctrl');
  function sync() { ctrl.hidden = !(track.scrollWidth > track.clientWidth + 4); }
  function step(dir) {
    var card = track.querySelector('.proj');
    track.scrollBy({ left: dir * (card.offsetWidth + 19), behavior: reduce ? 'auto' : 'smooth' });
  }
  document.getElementById('prev').addEventListener('click', function () { step(-1); });
  document.getElementById('next').addEventListener('click', function () { step(1); });
  window.addEventListener('resize', sync);
  sync();

  /* resume viewer, opens inside the page */
  var viewer = document.getElementById('viewer');
  var vmsg = document.getElementById('vmsg');
  var lastFocus = null;
  var PDF_B64 = '';
  function openViewer() {
    lastFocus = document.activeElement;
    vmsg.textContent = '';
    viewer.hidden = false;
    document.body.style.overflow = 'hidden';
    document.getElementById('vclose').focus();
  }
  function closeViewer() {
    viewer.hidden = true;
    document.body.style.overflow = '';
    if (lastFocus && lastFocus.focus) lastFocus.focus();
  }
  document.querySelectorAll('[data-open-resume]').forEach(function (b) { b.addEventListener('click', openViewer); });
  document.getElementById('vclose').addEventListener('click', closeViewer);
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && !viewer.hidden) closeViewer(); });
  document.getElementById('vscroll').addEventListener('click', function (e) { if (e.target === this) closeViewer(); });
  document.getElementById('dl').addEventListener('click', async function () {
    vmsg.textContent = '';
    try {
      var ds = window.claude && window.claude.use ? await window.claude.use('downloads') : null;
      if (!ds) { vmsg.textContent = 'Downloading is not available in this view. You can read the full resume above.'; return; }
      var bin = atob(PDF_B64), bytes = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      await ds.save({ filename: 'Jagadeeshwaran_T_Resume.pdf', data: bytes });
      vmsg.textContent = 'Saved. Thank you for viewing my resume.';
    } catch (err) {
      vmsg.textContent = err && err.code === 'declined' ? 'Download cancelled.' : 'Download is not available here. You can read the full resume above.';
    }
  });
})();


/* ===== Original script block 2 ===== */
(function () {
  var trigger = document.getElementById('open-email-picker');
  if (!trigger) return;
  var recipient = 'jagadeeshwaran024@gmail.com';
  var subject = 'Job Opportunity for Jagadeeshwaran T';
  var body = 'Hi Jagadeeshwaran,\n\nI came across your portfolio and would like to discuss a potential job opportunity with you.\n\nCompany:\nJob Title:\nJob Type: Full-time / Internship\nWork Location: On-site / Hybrid / Remote\nRequired Skills:\nPreferred Time for a Call:\n\nPlease let me know your availability so we can discuss the opportunity further.\n\nBest regards,\n[HR Name]\n[Designation]\n[Company Name]\n[Contact Information]';
  trigger.addEventListener('click', function () {
    var params = new URLSearchParams({ view: 'cm', fs: '1', to: recipient, su: subject, body: body });
    window.open('https://mail.google.com/mail/?' + params.toString(), '_blank', 'noopener,noreferrer');
  });
})();


/* ===== Original script block 3 ===== */
/* Add the Education-style animated accent to each Experience card without replacing its timeline dot. */
document.querySelectorAll('#education-experience-grid #experience .tl > li').forEach(function(card) {
  if (!card.querySelector(':scope > .experience-accent')) {
    var accent = document.createElement('span');
    accent.className = 'experience-accent';
    accent.setAttribute('aria-hidden', 'true');
    card.prepend(accent);
  }
});



/* ===== Contact form -> Express backend ===== */
(function () {
  const form = document.getElementById('portfolio-contact-form');
  if (!form) return;
  const status = document.getElementById('contact-form-status');
  const submit = form.querySelector('button[type="submit"]');
  const apiBase = (window.PORTFOLIO_API_URL || 'http://localhost:5000').replace(/\/$/, '');

  form.addEventListener('submit', async function (event) {
    event.preventDefault();
    if (!form.reportValidity()) return;
    const data = Object.fromEntries(new FormData(form).entries());
    if (data.website) return; // honeypot field for bots
    submit.disabled = true;
    const originalText = submit.textContent;
    submit.textContent = 'Sending…';
    status.textContent = 'Sending your message securely…';
    status.className = 'contact-form-status';
    try {
      const response = await fetch(apiBase + '/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: data.name, email: data.email, subject: data.subject, message: data.message })
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(result.error || 'Unable to send your message right now.');
      form.reset();
      status.textContent = 'Thanks! Your message was sent successfully.';
      status.className = 'contact-form-status success';
    } catch (error) {
      status.textContent = (error.message || 'Could not reach the contact service.') + ' You can email me directly at jagadeeshwaran024@gmail.com.';
      status.className = 'contact-form-status error';
    } finally {
      submit.disabled = false;
      submit.textContent = originalText;
    }
  });
})();
